-- Compatibility for mixed historical/new LoA SQL; modern fields remain authoritative.
ALTER TABLE quest_poi_points ADD COLUMN IF NOT EXISTS BlobIndex int unsigned NOT NULL DEFAULT 0;
UPDATE creature_text SET CreatureID=entry WHERE CreatureID=0 AND entry<>0;
ALTER TABLE `creature_text` DROP PRIMARY KEY, ADD PRIMARY KEY (CreatureID,GroupID,ID);
ALTER TABLE `creature_equip_template` DROP PRIMARY KEY, ADD PRIMARY KEY (CreatureID,ID);
ALTER TABLE `points_of_interest` DROP PRIMARY KEY, ADD PRIMARY KEY (ID);
ALTER TABLE `quest_poi` DROP PRIMARY KEY, ADD PRIMARY KEY (QuestID,Idx1);
ALTER TABLE `quest_poi_points` DROP PRIMARY KEY, ADD PRIMARY KEY (QuestID,BlobIndex,Idx1,Idx2);
UPDATE `creature_text` SET `entry`=`CreatureID`;
DROP TRIGGER IF EXISTS `loa_compat_creature_text_bi`;
DELIMITER $$
CREATE TRIGGER `loa_compat_creature_text_bi` BEFORE INSERT ON `creature_text` FOR EACH ROW BEGIN IF (NEW.`CreatureID` IS NULL OR CAST(NEW.`CreatureID` AS CHAR) IN ('','0')) AND NEW.`entry` IS NOT NULL THEN SET NEW.`CreatureID`=NEW.`entry`; END IF; SET NEW.`entry`=NEW.`CreatureID`; END$$
DELIMITER ;
DROP TRIGGER IF EXISTS `loa_compat_creature_text_bu`;
DELIMITER $$
CREATE TRIGGER `loa_compat_creature_text_bu` BEFORE UPDATE ON `creature_text` FOR EACH ROW BEGIN IF NOT (NEW.`entry` <=> OLD.`entry`) AND (NEW.`CreatureID` <=> OLD.`CreatureID`) THEN SET NEW.`CreatureID`=NEW.`entry`; END IF; SET NEW.`entry`=NEW.`CreatureID`; END$$
DELIMITER ;
